'use strict';
const fs=require('node:fs/promises'),path=require('node:path'),{spawn}=require('node:child_process'),readline=require('node:readline');
const {assert,readJSON,atomicJSON}=require('./core.cjs');
function friendCode({name,address,minecraft}){require('./multiplayer.cjs').address(address);assert(['26.3','1.21.11','1.21.1','1.20.1'].includes(minecraft),'Unsupported invite version.');return 'bora2.'+Buffer.from(JSON.stringify({name:String(name).slice(0,60),address,minecraft,provider:'playit'})).toString('base64url');}
function parseCode(value){assert(typeof value==='string'&&value.startsWith('bora2.')&&value.length<=2048,'Paste a Boralances Playit friend code.');let item;try{item=JSON.parse(Buffer.from(value.slice(6),'base64url'));}catch{throw Error('Invalid friend code.');}require('./multiplayer.cjs').address(item.address);assert(typeof item.name==='string'&&item.name.length<=60&&['26.3','1.21.11','1.21.1','1.20.1'].includes(item.minecraft),'Invalid friend code.');return {kind:'address',name:item.name,address:item.address,minecraft:item.minecraft,provider:'playit'};}
class PlayitManager {
 constructor({data,assets,encrypt,decrypt,emit=()=>{}}){Object.assign(this,{data,assets,encrypt,decrypt,emit});this.info={running:false,status:'Start a server, then Share with Playit to link a free Minecraft Java tunnel.',address:'',claim:''};}
 public(){return {...this.info};}
 async start(entry,java){if(this.child){assert(this.info.serverId===entry.config.id,'Stop the current Playit tunnel before sharing another world.');return this.public();}const directory=path.join(this.data,'playit');await fs.mkdir(directory,{recursive:true});const saved=await readJSON(path.join(directory,'agent.secure.json'),null);let secret=null;if(saved)try{secret=this.decrypt(saved.value).secret;}catch{throw Error('Saved Playit credentials cannot be opened on this Windows account. Relink Playit from its panel.');}const bundled=path.join(this.assets,'server/boralances-playit-agent.jar');assert((await fs.stat(bundled).catch(()=>null))?.isFile(),'Playit helper is missing; reinstall the launcher.');const jar=path.join(directory,'boralances-playit-agent.jar');await fs.writeFile(jar,await fs.readFile(bundled));const child=spawn(java,['-Xms32M','-Xmx128M','-XX:MaxDirectMemorySize=32M','-jar',jar],{cwd:directory,windowsHide:true,stdio:['pipe','pipe','pipe']});this.child=child;this.info={running:true,serverId:entry.config.id,status:'Connecting to Playit…',address:'',claim:''};readline.createInterface({input:child.stdout}).on('line',line=>{if(line.length>8192)return;let event;try{event=JSON.parse(line);}catch{return;}if(event.type==='secret'){if(typeof event.value!=='string'||event.value.length>4096)return;atomicJSON(path.join(directory,'agent.secure.json'),{value:this.encrypt({secret:event.value})}).catch(()=>{this.info.status='Could not securely save the Playit account. Stop and relink it.';this.stop();});return;}if(event.type==='claim'&&/^https:\/\/playit\.gg\/claim\/[a-z0-9]{6}$/.test(event.value))this.info.claim=event.value;if(event.type==='address'){try{require('./multiplayer.cjs').address(event.value);this.info.address=event.value;this.info.claim='';}catch{return;}}if(event.type==='status'||event.type==='error')this.info.status=String(event.value).slice(0,500);this.emit('server-event',{id:entry.config.id,status:this.info.status});});child.stderr.on('data',()=>{});child.on('error',error=>{this.info.status='Could not start the Playit helper: '+error.code;});child.on('close',()=>{if(this.child===child){this.child=null;this.info.running=false;this.info.address='';this.info.claim='';this.emit('server-event',{id:entry.config.id,status:'Playit tunnel stopped.'});}});child.stdin.on('error',()=>{});child.stdin.write(JSON.stringify({port:entry.gamePort,directory,...(secret?{secret}:{})})+'\n');return this.public();}
 stop(){const child=this.child;if(!child)return;this.info.status='Stopping Playit…';child.stdin.end('stop\n');const timer=setTimeout(()=>{if(this.child===child)child.kill();},15000);timer.unref();}
}
module.exports={PlayitManager,friendCode,parseCode};
